async function check(index,fn){const row=report.records[index-1];phase=row.name;const start=performance.now();row.status='RUNNING';save();console.log(JSON.stringify({id:row.id,status:'START'}));try{row.detail=await fn()??{};row.status='PASS';row.elapsed_ms=Math.round(performance.now()-start);console.log(JSON.stringify({id:row.id,status:'PASS'}));save();}catch(error){row.status='FAIL';row.error_name=error.name;try{await captureFailure(error);}catch(diagnosticError){report.diagnostic_capture_error=cleanError(diagnosticError.message);}console.error(cleanError(error.stack??error.message));row.error_message=cleanError(error.message);row.error_stack=cleanError(error.stack??'');row.elapsed_ms=Math.round(performance.now()-start);save();throw error;}}
